import React from 'react';
import { Stage } from 'react-pixi-fiber';
import { isMobileView, scrHeight, scrWidth } from './utils/other';
import { MainGameStage } from './stages/MainGameStage';

import './App.css';

const App = () => {

  const opts = isMobileView ? { height: scrHeight, width: scrWidth} : { height: 600, width: 800 };
  return (
    <div className='main'>
      <Stage className='stage' options={{ backgroundColor: 0x664131, ...opts }}>
        <MainGameStage />
      </Stage>
    </div>
  );
}


export default App;
